/* From Uiverse.io by imPradhyumn - Tags: card, transition, hover slide, card hover, 3d card */
.__UIV_SCOPE__ .card {
  width: 190px;
  height: 254px;
  box-shadow: 0 3px 10px rgb(0 0 0 / 0.2);
  position: relative;
}

.__UIV_SCOPE__ .remove-when-use {
  text-align: center;
  width: 100%;
  position: absolute;
  color: black;
  top: 85px;
  font-weight: bold;
}

.__UIV_SCOPE__ .details > p {
  font-size: .8em;
  margin-top: .5em;
}

.__UIV_SCOPE__ .details > label {
  font-weight: bold;
}

.__UIV_SCOPE__ .details {
  color: white;
  box-shadow: 0 3px 10px rgb(0 0 0 / 0.2);
  width: 100%;
  background-color: rgba(0,0,0,0.5);
  position: absolute;
  bottom: 0;
  height: 2.6em;
  transition: height .5s ease-in-out;
  padding: 0.6em;
  overflow: hidden;
}

.__UIV_SCOPE__ .card:hover > .details {
  height: 6.7em;
}
